typedef unsigned int big_int;

class string_buf
{
public:
  big_int *data;
  int ref_count;
  int char_length;
  int block_length;
  int max_blocks;

  inline int compare(const char *str) const
  {
    const char *a = reinterpret_cast<const char *>(data);
    int i;
    for (i = 0; i < char_length; i++)
    {
      if (str[i] == '\0')
        return -1;
      if (a[i] == str[i])
        continue;
      if (str[i] > a[i])
        return 1;
      if (str[i] < a[i])
        return -1;
    }
    if (str[i] == '\0')
      return 0;
    return 1;
  }

  inline bool is_equal(const char *str) const
  {
    return compare(str) == 0;
  }
};

class stringx
{
  friend inline bool operator==(const stringx& lhs, const char *rhs);

protected:
  char *chars;
  string_buf *my_buf;

public:
  stringx();
  ~stringx();
  stringx &operator=(const char *str);

  inline const char *c_str() const
  {
    return chars;
  }
};

inline bool operator==(const stringx& lhs, const char *rhs)
{
  return lhs.my_buf->is_equal(rhs);
}

class game
{
public:
  stringx get_beach_name(void);
};

extern game *g_game_ptr;

typedef int nslSourceId;
typedef int nslSoundId;

enum
{
  NSL_INVALID_ID = -1
};

nslSourceId nslLoadSource(const char *soundSourceName);
nslSoundId nslAddSound(nslSourceId soundSource);
void nslPlaySound(nslSoundId soundToPlay);

class SFXEngine
{
public:
  void playRain();
};

void SFXEngine::playRain( )
{
  stringx name;

  if ( g_game_ptr->get_beach_name( ) == "CORTES BANK" )
    name = "amb_rain01";
  else if ( g_game_ptr->get_beach_name( ) == "JEFFERSON BAY" )
    name = "amb_rain02";
  else
    return;

  nslSourceId rainSrc = nslLoadSource( name.c_str( ) );
  if ( rainSrc != NSL_INVALID_ID )
  {
    nslSoundId rainSnd = nslAddSound( rainSrc );
    if ( rainSnd != NSL_INVALID_ID )
    {
      nslPlaySound( rainSnd );
    }
  }

}
